/// Paint the mark in `rect`: whole, centred, aspect kept, in its own colours.
pub fn paint(painter: &egui::Painter, rect: egui::Rect) {
    let (w, h) = SIZE;
    let k = (rect.width() / w).min(rect.height() / h);
    let o = rect.center() - egui::vec2(w * k / 2.0, h * k / 2.0);
    for &(points, triangles, [r, g, b]) in SHAPES {
        let mut mesh = egui::Mesh::default();
        for &[x, y] in points {
            mesh.colored_vertex(o + egui::vec2(x * k, y * k), egui::Color32::from_rgb(r, g, b));
        }
        for &[a, b, c] in triangles {
            mesh.add_triangle(a, b, c);
        }
        painter.add(egui::Shape::mesh(mesh));
    }
}
